#!/usr/bin/env python3
"""
Differential fuzzer comparing /work/minicore against an independent textbook
reference implementation:
  - Dunfield-Krishnaswami Bidirectional Typechecker (§4.3)
  - Big-step Tree-Walking Operational Semantics Evaluator (§5.2)
"""
from __future__ import annotations

import importlib.machinery
import importlib.util
import random
import sys
import time

sys.set_int_max_str_digits(0)
sys.setrecursionlimit(200_000)

# Load /work/minicore directly as a module for fast in-process fuzzing (10,000+ cases)
loader = importlib.machinery.SourceFileLoader("minicore_mod", "/work/minicore")
spec = importlib.util.spec_from_loader("minicore_mod", loader)
assert spec is not None
mc = importlib.util.module_from_spec(spec)
loader.exec_module(mc)


# ---------------------------------------------------------------------------
# Independent Reference: Bidirectional Typechecker (§4.3)
# ---------------------------------------------------------------------------


class RefUnknown:
    def __init__(self) -> None:
        self.sol: object = None


REF_INT = "Int"
REF_BOOL = "Bool"


def ref_deref(t: object) -> object:
    while isinstance(t, RefUnknown) and t.sol is not None:
        t = t.sol
    return t


def ref_occurs(u: RefUnknown, t: object) -> bool:
    t = ref_deref(t)
    if t is u:
        return True
    if isinstance(t, tuple):  # ("->", a, b)
        return ref_occurs(u, t[1]) or ref_occurs(u, t[2])
    return False


class RefTypeError(Exception):
    pass


def ref_equate(t1: object, t2: object) -> None:
    t1 = ref_deref(t1)
    t2 = ref_deref(t2)
    if t1 is t2 or (isinstance(t1, str) and t1 == t2):
        return
    if isinstance(t1, RefUnknown):
        if ref_occurs(t1, t2):
            raise RefTypeError()
        t1.sol = t2
        return
    if isinstance(t2, RefUnknown):
        if ref_occurs(t2, t1):
            raise RefTypeError()
        t2.sol = t1
        return
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        ref_equate(t1[1], t2[1])
        ref_equate(t1[2], t2[2])
        return
    raise RefTypeError()


def conv_ast_type(ty: object) -> object:
    if ty is mc.T_INT:
        return REF_INT
    if ty is mc.T_BOOL:
        return REF_BOOL
    if isinstance(ty, mc.TArrow):
        return ("->", conv_ast_type(ty.dom), conv_ast_type(ty.cod))
    raise AssertionError(ty)


def ref_synth(ctx: list[tuple[str, object]], e: object) -> object:
    if isinstance(e, mc.IntLit):
        return REF_INT
    if isinstance(e, mc.BoolLit):
        return REF_BOOL
    if isinstance(e, mc.Var):
        # §4.2: rightmost binding of x in Γ
        for k, v in reversed(ctx):
            if k == e.name:
                return v
        raise RefTypeError()
    if isinstance(e, mc.Lam):
        u = RefUnknown()
        ret = ref_synth(ctx + [(e.param, u)], e.body)
        return ("->", u, ret)
    if isinstance(e, mc.App):
        ft = ref_deref(ref_synth(ctx, e.fn))
        if isinstance(ft, tuple):
            ref_check(ctx, e.arg, ft[1])
            return ft[2]
        if isinstance(ft, RefUnknown):
            u1, u2 = RefUnknown(), RefUnknown()
            ft.sol = ("->", u1, u2)
            ref_check(ctx, e.arg, u1)
            return u2
        raise RefTypeError()
    if isinstance(e, mc.BinOp):
        ref_check(ctx, e.left, REF_INT)
        ref_check(ctx, e.right, REF_INT)
        return REF_INT if e.op <= mc.OP_MOD else REF_BOOL
    if isinstance(e, mc.If):
        ref_check(ctx, e.cond, REF_BOOL)
        t1 = ref_synth(ctx, e.then_b)
        ref_check(ctx, e.else_b, t1)
        return t1
    if isinstance(e, mc.Anno):
        T = conv_ast_type(e.ty)
        ref_check(ctx, e.expr, T)
        return T
    if isinstance(e, mc.Let):
        if e.ty is not None:
            T = conv_ast_type(e.ty)
            ref_check(ctx, e.val_expr, T)
            return ref_synth(ctx + [(e.name, T)], e.body)
        t1 = ref_synth(ctx, e.val_expr)
        return ref_synth(ctx + [(e.name, t1)], e.body)
    if isinstance(e, mc.LetRec):
        T = conv_ast_type(e.ty)
        ctx2 = ctx + [(e.name, T)]
        ref_check(ctx2, e.fn_expr, T)
        return ref_synth(ctx2, e.body)
    raise AssertionError(e)


def ref_check(ctx: list[tuple[str, object]], e: object, expected: object) -> None:
    expected = ref_deref(expected)
    if isinstance(e, mc.Lam) and isinstance(expected, tuple):
        ref_check(ctx + [(e.param, expected[1])], e.body, expected[2])
        return
    if isinstance(e, mc.If):
        ref_check(ctx, e.cond, REF_BOOL)
        ref_check(ctx, e.then_b, expected)
        ref_check(ctx, e.else_b, expected)
        return
    if isinstance(e, mc.Let):
        if e.ty is not None:
            T = conv_ast_type(e.ty)
            ref_check(ctx, e.val_expr, T)
            ref_check(ctx + [(e.name, T)], e.body, expected)
        else:
            t1 = ref_synth(ctx, e.val_expr)
            ref_check(ctx + [(e.name, t1)], e.body, expected)
        return
    actual = ref_synth(ctx, e)
    ref_equate(actual, expected)


# ---------------------------------------------------------------------------
# Independent Reference: Big-Step Tree-Walking Evaluator (§5.2)
# ---------------------------------------------------------------------------


class RefRuntimeError(Exception):
    pass


class StepLimitExceeded(Exception):
    pass


class RefClosure:
    def __init__(self, param: str, body: object, env: dict[str, object]) -> None:
        self.param = param
        self.body = body
        self.env = env


def ref_eval_program(program: object, max_steps: int = 20_000) -> str:
    steps = 0

    def ev(env: dict[str, object], e: object) -> object:
        nonlocal steps
        steps += 1
        if steps > max_steps:
            raise StepLimitExceeded()
        if isinstance(e, mc.IntLit):
            return e.val
        if isinstance(e, mc.BoolLit):
            return e.val
        if isinstance(e, mc.Var):
            return env[e.name]
        if isinstance(e, mc.Lam):
            return RefClosure(e.param, e.body, dict(env))
        if isinstance(e, mc.Anno):
            return ev(env, e.expr)
        if isinstance(e, mc.App):
            c = ev(env, e.fn)
            assert isinstance(c, RefClosure)
            v = ev(env, e.arg)
            new_env = dict(c.env)
            new_env[c.param] = v
            return ev(new_env, c.body)
        if isinstance(e, mc.BinOp):
            a = ev(env, e.left)
            b = ev(env, e.right)
            assert type(a) is int and type(b) is int
            if e.op == mc.OP_ADD:
                return a + b
            if e.op == mc.OP_SUB:
                return a - b
            if e.op == mc.OP_MUL:
                return a * b
            if e.op == mc.OP_DIV:
                if b == 0:
                    raise RefRuntimeError()
                return a // b
            if e.op == mc.OP_MOD:
                if b == 0:
                    raise RefRuntimeError()
                return a % b
            if e.op == mc.OP_EQ:
                return a == b
            if e.op == mc.OP_LT:
                return a < b
            raise AssertionError(e.op)
        if isinstance(e, mc.If):
            c = ev(env, e.cond)
            assert type(c) is bool
            return ev(env, e.then_b if c else e.else_b)
        if isinstance(e, mc.Let):
            v1 = ev(env, e.val_expr)
            new_env = dict(env)
            new_env[e.name] = v1
            return ev(new_env, e.body)
        if isinstance(e, mc.LetRec):
            rec_env = dict(env)
            clos = RefClosure(e.fn_expr.param, e.fn_expr.body, rec_env)
            rec_env[e.name] = clos
            return ev(rec_env, e.body)
        raise AssertionError(e)

    v = ev({}, program)
    if type(v) is bool:
        return "True" if v else "False"
    if type(v) is int:
        return str(v)
    if isinstance(v, RefClosure):
        return "<function>"
    raise AssertionError(v)


def run_reference(raw: bytes) -> str:
    try:
        kinds, vals = mc.tokenize(raw)
        prog = mc.Parser(kinds, vals).parse_program()
    except mc.MCParseError:
        return "ParseError"
    try:
        ref_synth([], prog)
    except RefTypeError:
        return "TypeError"
    try:
        return ref_eval_program(prog)
    except RefRuntimeError:
        return "RuntimeError"


def run_dut(raw: bytes) -> str:
    try:
        return mc.execute_bytes(raw)
    except mc.MCParseError:
        return "ParseError"
    except mc.MCTypeError:
        return "TypeError"
    except mc.MCRuntimeError:
        return "RuntimeError"


# ---------------------------------------------------------------------------
# Random Program Generators (both well-typed and arbitrary/mutated)
# ---------------------------------------------------------------------------

NAMES = ["x", "y", "z", "f", "g", "_a", "k"]


def gen_type(rng: random.Random, depth: int = 0) -> str:
    if depth >= 2 or rng.random() < 0.6:
        return rng.choice(["Int", "Bool"])
    a = gen_type(rng, depth + 1)
    b = gen_type(rng, depth + 1)
    if "->" in a:
        a = f"({a})"
    return f"{a} -> {b}"


def gen_typed_expr(
    rng: random.Random, env: list[tuple[str, str]], target_ty: str, depth: int
) -> str:
    candidates = [n for n, t in reversed(env) if dict(env).get(n) == t and t == target_ty]
    # Exact rightmost-aware lookup:
    latest: dict[str, str] = {}
    for n, t in env:
        latest[n] = t
    matching_vars = [n for n, t in latest.items() if t == target_ty]

    if depth <= 0:
        if matching_vars and rng.random() < 0.6:
            return rng.choice(matching_vars)
        if target_ty == "Int":
            v = rng.choice([0, 1, 2, 3, 5, 7, 10, -1, -7, -15])
            return str(v) if v >= 0 else f"(0 - {-v})"
        if target_ty == "Bool":
            return rng.choice(["True", "False"])
        # Arrow type A -> B: parse top-level arrow
        dom, cod = split_arrow(target_ty)
        p = rng.choice(NAMES)
        body = gen_typed_expr(rng, env + [(p, dom)], cod, 0)
        return f"(/{p} -> {body})"

    choice = rng.random()
    if matching_vars and choice < 0.20:
        return rng.choice(matching_vars)

    if choice < 0.35:
        c = gen_typed_expr(rng, env, "Bool", depth - 1)
        t_b = gen_typed_expr(rng, env, target_ty, depth - 1)
        e_b = gen_typed_expr(rng, env, target_ty, depth - 1)
        return f"(if {c} then {t_b} else {e_b})"

    if choice < 0.55:
        nm = rng.choice(NAMES)
        bt = gen_type(rng, 1)
        be = gen_typed_expr(rng, env, bt, depth - 1)
        body = gen_typed_expr(rng, env + [(nm, bt)], target_ty, depth - 1)
        if rng.random() < 0.4:
            return f"(let {nm} : {bt} = {be} in {body})"
        return f"(let {nm} = {be} in {body})"

    if choice < 0.68:
        # Application: (/p -> body) arg
        arg_ty = gen_type(rng, 1)
        fn_ty = f"({arg_ty}) -> ({target_ty})"
        fn_e = gen_typed_expr(rng, env, fn_ty, depth - 1)
        arg_e = gen_typed_expr(rng, env, arg_ty, depth - 1)
        if rng.random() < 0.25:
            return f"(({fn_e} : {fn_ty}) {arg_e})"
        return f"({fn_e} {arg_e})"

    if choice < 0.78:
        # Bounded recursion via let rec!
        fn_name = rng.choice(["f", "g", "x"])
        p_name = rng.choice(["n", "x", "f"])
        limit_n = rng.randint(0, 5)
        base = gen_typed_expr(rng, env + [(p_name, "Int")], target_ty, depth - 1)
        if target_ty == "Int" and p_name != fn_name:
            step = f"({fn_name} ({p_name} - 1) + {base})"
        elif p_name != fn_name:
            step = f"({fn_name} ({p_name} - 1))"
        else:
            step = base
        lam = f"/{p_name} -> if {p_name} < 1 then {base} else {step}"
        if rng.random() < 0.3:
            lam = f"({lam})"
        body = gen_typed_expr(
            rng, env + [(fn_name, f"Int -> ({target_ty})")], target_ty, depth - 1
        )
        call_or_body = (
            f"({fn_name} {limit_n})" if rng.random() < 0.6 else body
        )
        return f"(let rec {fn_name} : Int -> ({target_ty}) = {lam} in {call_or_body})"

    if target_ty == "Int":
        op = rng.choice(["+", "-", "*", "//", "%"])
        a = gen_typed_expr(rng, env, "Int", depth - 1)
        b = gen_typed_expr(rng, env, "Int", depth - 1)
        return f"({a} {op} {b})"

    if target_ty == "Bool":
        op = rng.choice(["==", "<"])
        a = gen_typed_expr(rng, env, "Int", depth - 1)
        b = gen_typed_expr(rng, env, "Int", depth - 1)
        return f"({a} {op} {b})"

    dom, cod = split_arrow(target_ty)
    p = rng.choice(NAMES)
    body = gen_typed_expr(rng, env + [(p, dom)], cod, depth - 1)
    return f"(/{p} -> {body})"


def split_arrow(ty: str) -> tuple[str, str]:
    ty = ty.strip()
    while ty.startswith("(") and ty.endswith(")"):
        # Check if outer parens match
        d = 0
        matched = True
        for i, ch in enumerate(ty):
            if ch == "(":
                d += 1
            elif ch == ")":
                d -= 1
                if d == 0 and i < len(ty) - 1:
                    matched = False
                    break
        if matched:
            ty = ty[1:-1].strip()
        else:
            break
    d = 0
    for i in range(len(ty) - 1):
        ch = ty[i]
        if ch == "(":
            d += 1
        elif ch == ")":
            d -= 1
        elif d == 0 and ty[i : i + 2] == "->":
            return ty[:i].strip(), ty[i + 2 :].strip()
    raise AssertionError(f"not an arrow type: {ty!r}")


def gen_untyped_expr(rng: random.Random, depth: int) -> str:
    if depth <= 0:
        return rng.choice(["0", "1", "2", "True", "False", "x", "y", "f"])
    k = rng.randrange(8)
    if k == 0:
        p = rng.choice(NAMES)
        return f"/{p} -> {gen_untyped_expr(rng, depth - 1)}"
    if k == 1:
        a = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        return f"({a}) ({b})"
    if k == 2:
        op = rng.choice(["+", "-", "*", "//", "%", "==", "<"])
        a = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        return f"({a}) {op} ({b})"
    if k == 3:
        c = gen_untyped_expr(rng, depth - 1)
        t = gen_untyped_expr(rng, depth - 1)
        e = gen_untyped_expr(rng, depth - 1)
        return f"if {c} then {t} else {e}"
    if k == 4:
        nm = rng.choice(NAMES)
        v = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        if rng.random() < 0.3:
            return f"let {nm} : {gen_type(rng, 1)} = {v} in {b}"
        return f"let {nm} = {v} in {b}"
    if k == 5:
        nm = rng.choice(NAMES)
        p = rng.choice(NAMES)
        ty = gen_type(rng, 1)
        fb = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        return f"let rec {nm} : {ty} = /{p} -> {fb} in {b}"
    if k == 6:
        e = gen_untyped_expr(rng, depth - 1)
        return f"({e} : {gen_type(rng, 1)})"
    # Occasional syntax mutations
    e = gen_untyped_expr(rng, depth - 1)
    mut = rng.choice([
        f"{e} < 1 < 2",
        f"let rec f = /x -> {e} in f",
        f"let rec x : Int = {e} in x",
        f"({e}) /x -> x",
        f"let _ = {e} in 1",
        f"{e} -- comment\n",
    ])
    return mut


def main() -> None:
    rng = random.Random(20250301)
    t0 = time.perf_counter()
    outcomes: dict[str, int] = {}
    skipped = 0
    total = 8000

    for i in range(total):
        if i % 2 == 0:
            tgt = gen_type(rng, 0)
            src = gen_typed_expr(rng, [], tgt, rng.randint(1, 4))
        else:
            src = gen_untyped_expr(rng, rng.randint(1, 4))

        raw = src.encode("utf-8")
        try:
            ref_out = run_reference(raw)
        except StepLimitExceeded:
            skipped += 1
            continue
        dut_out = run_dut(raw)
        if ref_out != dut_out:
            print(f"MISMATCH on case #{i}!")
            print("Source:\n" + src)
            print(f"Ref: {ref_out!r}")
            print(f"DUT: {dut_out!r}")
            sys.exit(1)
        key = ref_out if ref_out in ("ParseError", "TypeError", "RuntimeError", "<function>", "True", "False") else "<int>"
        outcomes[key] = outcomes.get(key, 0) + 1

    t1 = time.perf_counter()
    print(f"Differential fuzzing passed {total - skipped}/{total} cases (skipped {skipped} non-terminating) in {t1 - t0:.2f}s")
    print("Outcome distribution:", outcomes)


if __name__ == "__main__":
    main()

