#!/usr/bin/env python3
"""
Full-pipeline differential fuzzer comparing /work/minicore against a 100%
independent textbook reference implementation of all 4 phases:
  1. Character-by-character Reference Lexer (§1, §2)
  2. Textbook Grammar Reference Parser (§3)
  3. Dunfield-Krishnaswami Bidirectional Typechecker (§4.3)
  4. Big-step Tree-Walking Operational Semantics Evaluator (§5.2)
"""
from __future__ import annotations

import importlib.machinery
import importlib.util
import random
import sys
import time

sys.set_int_max_str_digits(0)
sys.setrecursionlimit(200_000)

loader = importlib.machinery.SourceFileLoader("minicore_mod", "/work/minicore")
spec = importlib.util.spec_from_loader("minicore_mod", loader)
assert spec is not None
mc = importlib.util.module_from_spec(spec)
loader.exec_module(mc)


# ---------------------------------------------------------------------------
# Phase 1: Independent Character-by-Character Reference Lexer (§1, §2)
# ---------------------------------------------------------------------------


class RefParseError(Exception):
    pass


REF_WS = frozenset(" \t\n\r\f\v")
REF_DIGITS = frozenset("0123456789")
REF_LOWER = frozenset("abcdefghijklmnopqrstuvwxyz_")
REF_UPPER = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
REF_IDENT_CONT = REF_LOWER | REF_UPPER | REF_DIGITS
REF_KEYWORDS = frozenset({"let", "rec", "in", "if", "then", "else"})
REF_RESERVED = frozenset({"match", "with", "type", "forall"})
REF_VALID_UPPER = frozenset({"True", "False", "Int", "Bool"})


def ref_lex(raw: bytes) -> list[tuple[str, str]]:
    for b in raw:
        if b >= 128:
            raise RefParseError("non-ASCII")
    s = raw.decode("ascii")
    n = len(s)
    i = 0
    tokens: list[tuple[str, str]] = []
    while i < n:
        ch = s[i]
        if ch in REF_WS:
            i += 1
            continue
        if ch == "-" and i + 1 < n and s[i + 1] == "-":
            i += 2
            while i < n and s[i] != "\n":
                i += 1
            continue
        if ch in REF_DIGITS:
            j = i + 1
            while j < n and s[j] in REF_DIGITS:
                j += 1
            tokens.append(("INT", s[i:j]))
            i = j
            continue
        if ch in REF_LOWER:
            j = i + 1
            while j < n and s[j] in REF_IDENT_CONT:
                j += 1
            w = s[i:j]
            if w == "_" or w in REF_RESERVED:
                raise RefParseError(f"bad ident {w}")
            if w in REF_KEYWORDS:
                tokens.append((w, w))
            else:
                tokens.append(("IDENT", w))
            i = j
            continue
        if ch in REF_UPPER:
            j = i + 1
            while j < n and s[j] in REF_IDENT_CONT:
                j += 1
            w = s[i:j]
            if w not in REF_VALID_UPPER:
                raise RefParseError(f"bad upper {w}")
            tokens.append((w, w))
            i = j
            continue
        if ch == "-" and i + 1 < n and s[i + 1] == ">":
            tokens.append(("->", "->"))
            i += 2
            continue
        if ch == "/" and i + 1 < n and s[i + 1] == "/":
            tokens.append(("//", "//"))
            i += 2
            continue
        if ch == "=" and i + 1 < n and s[i + 1] == "=":
            tokens.append(("==", "=="))
            i += 2
            continue
        if ch in "()/+-%*<=:":
            tokens.append((ch, ch))
            i += 1
            continue
        raise RefParseError(f"bad char {ch!r}")
    tokens.append(("EOF", ""))
    return tokens


# ---------------------------------------------------------------------------
# Phase 2: Independent Reference Parser (§3) with explicit ("paren", e) AST!
# ---------------------------------------------------------------------------


class RefParser:
    def __init__(self, toks: list[tuple[str, str]]) -> None:
        self.toks = toks
        self.p = 0

    def cur(self) -> str:
        return self.toks[self.p][0]

    def eat(self, kind: str) -> str:
        if self.toks[self.p][0] != kind:
            raise RefParseError(f"expected {kind}, got {self.toks[self.p][0]}")
        v = self.toks[self.p][1]
        self.p += 1
        return v

    def parse(self) -> tuple:
        e = self.p_expr()
        self.eat("EOF")
        return e

    def p_expr(self) -> tuple:
        k = self.cur()
        if k == "/":
            self.eat("/")
            x = self.eat("IDENT")
            self.eat("->")
            return ("lam", x, self.p_expr())
        if k == "let":
            self.eat("let")
            if self.cur() == "rec":
                self.eat("rec")
                f = self.eat("IDENT")
                self.eat(":")
                ty = self.p_type()
                self.eat("=")
                rhs = self.p_expr()
                # Unwrap ONLY ("paren", ...), NOT ("anno", ...)
                u = rhs
                while u[0] == "paren":
                    u = u[1]
                if u[0] != "lam":
                    raise RefParseError("let rec rhs must be lambda")
                self.eat("in")
                body = self.p_expr()
                return ("letrec", f, ty, u, body)
            x = self.eat("IDENT")
            ty = None
            if self.cur() == ":":
                self.eat(":")
                ty = self.p_type()
            self.eat("=")
            e1 = self.p_expr()
            self.eat("in")
            e2 = self.p_expr()
            return ("let", x, ty, e1, e2)
        if k == "if":
            self.eat("if")
            c = self.p_expr()
            self.eat("then")
            t = self.p_expr()
            self.eat("else")
            el = self.p_expr()
            return ("if", c, t, el)
        return self.p_cmp()

    def p_cmp(self) -> tuple:
        a = self.p_add()
        if self.cur() in ("==", "<"):
            op = self.eat(self.cur())
            b = self.p_add()
            return ("binop", op, a, b)
        return a

    def p_add(self) -> tuple:
        a = self.p_mul()
        while self.cur() in ("+", "-"):
            op = self.eat(self.cur())
            a = ("binop", op, a, self.p_mul())
        return a

    def p_mul(self) -> tuple:
        a = self.p_app()
        while self.cur() in ("*", "//", "%"):
            op = self.eat(self.cur())
            a = ("binop", op, a, self.p_app())
        return a

    def p_app(self) -> tuple:
        a = self.p_atom()
        while self.cur() in ("IDENT", "INT", "True", "False", "("):
            a = ("app", a, self.p_atom())
        return a

    def p_atom(self) -> tuple:
        k = self.cur()
        if k == "IDENT":
            return ("var", self.eat("IDENT"))
        if k == "INT":
            return ("int", int(self.eat("INT")))
        if k == "True":
            self.eat("True")
            return ("bool", True)
        if k == "False":
            self.eat("False")
            return ("bool", False)
        if k == "(":
            self.eat("(")
            e = self.p_expr()
            if self.cur() == ":":
                self.eat(":")
                ty = self.p_type()
                self.eat(")")
                return ("anno", e, ty)
            self.eat(")")
            return ("paren", e)
        raise RefParseError("atom")

    def p_type(self) -> object:
        a = self.p_tatom()
        if self.cur() == "->":
            self.eat("->")
            return ("->", a, self.p_type())
        return a

    def p_tatom(self) -> object:
        k = self.cur()
        if k == "Int":
            self.eat("Int")
            return "Int"
        if k == "Bool":
            self.eat("Bool")
            return "Bool"
        if k == "(":
            self.eat("(")
            t = self.p_type()
            self.eat(")")
            return t
        raise RefParseError("tatom")


# ---------------------------------------------------------------------------
# Phase 3: Independent Bidirectional Typechecker (§4.3)
# ---------------------------------------------------------------------------


class RefUnknown:
    def __init__(self) -> None:
        self.sol: object = None


class RefTypeError(Exception):
    pass


def ref_deref(t: object) -> object:
    while isinstance(t, RefUnknown) and t.sol is not None:
        t = t.sol
    return t


def ref_occurs(u: RefUnknown, t: object) -> bool:
    t = ref_deref(t)
    if t is u:
        return True
    if isinstance(t, tuple):
        return ref_occurs(u, t[1]) or ref_occurs(u, t[2])
    return False


def ref_equate(t1: object, t2: object) -> None:
    t1 = ref_deref(t1)
    t2 = ref_deref(t2)
    if t1 is t2 or (isinstance(t1, str) and t1 == t2):
        return
    if isinstance(t1, RefUnknown):
        if ref_occurs(t1, t2):
            raise RefTypeError()
        t1.sol = t2
        return
    if isinstance(t2, RefUnknown):
        if ref_occurs(t2, t1):
            raise RefTypeError()
        t2.sol = t1
        return
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        ref_equate(t1[1], t2[1])
        ref_equate(t1[2], t2[2])
        return
    raise RefTypeError()


def ref_synth(ctx: list[tuple[str, object]], e: tuple) -> object:
    tag = e[0]
    if tag == "paren":
        return ref_synth(ctx, e[1])
    if tag == "int":
        return "Int"
    if tag == "bool":
        return "Bool"
    if tag == "var":
        for k, v in reversed(ctx):
            if k == e[1]:
                return v
        raise RefTypeError()
    if tag == "lam":
        u = RefUnknown()
        return ("->", u, ref_synth(ctx + [(e[1], u)], e[2]))
    if tag == "app":
        ft = ref_deref(ref_synth(ctx, e[1]))
        if isinstance(ft, tuple):
            ref_check(ctx, e[2], ft[1])
            return ft[2]
        if isinstance(ft, RefUnknown):
            u1, u2 = RefUnknown(), RefUnknown()
            ft.sol = ("->", u1, u2)
            ref_check(ctx, e[2], u1)
            return u2
        raise RefTypeError()
    if tag == "binop":
        ref_check(ctx, e[2], "Int")
        ref_check(ctx, e[3], "Int")
        return "Bool" if e[1] in ("==", "<") else "Int"
    if tag == "if":
        ref_check(ctx, e[1], "Bool")
        t1 = ref_synth(ctx, e[2])
        ref_check(ctx, e[3], t1)
        return t1
    if tag == "anno":
        ref_check(ctx, e[1], e[2])
        return e[2]
    if tag == "let":
        _, x, ty, e1, e2 = e
        if ty is not None:
            ref_check(ctx, e1, ty)
            return ref_synth(ctx + [(x, ty)], e2)
        t1 = ref_synth(ctx, e1)
        return ref_synth(ctx + [(x, t1)], e2)
    if tag == "letrec":
        _, f, ty, lam_e, body = e
        ctx2 = ctx + [(f, ty)]
        ref_check(ctx2, lam_e, ty)
        return ref_synth(ctx2, body)
    raise AssertionError(e)


def ref_check(ctx: list[tuple[str, object]], e: tuple, expected: object) -> None:
    expected = ref_deref(expected)
    tag = e[0]
    if tag == "paren":
        ref_check(ctx, e[1], expected)
        return
    if tag == "lam" and isinstance(expected, tuple):
        ref_check(ctx + [(e[1], expected[1])], e[2], expected[2])
        return
    if tag == "if":
        ref_check(ctx, e[1], "Bool")
        ref_check(ctx, e[2], expected)
        ref_check(ctx, e[3], expected)
        return
    if tag == "let":
        _, x, ty, e1, e2 = e
        if ty is not None:
            ref_check(ctx, e1, ty)
            ref_check(ctx + [(x, ty)], e2, expected)
        else:
            t1 = ref_synth(ctx, e1)
            ref_check(ctx + [(x, t1)], e2, expected)
        return
    ref_equate(ref_synth(ctx, e), expected)


# ---------------------------------------------------------------------------
# Phase 4: Independent Big-Step Evaluator (§5.2)
# ---------------------------------------------------------------------------


class RefRuntimeError(Exception):
    pass


class StepLimitExceeded(Exception):
    pass


class RefClosure:
    def __init__(self, param: str, body: tuple, env: dict[str, object]) -> None:
        self.param = param
        self.body = body
        self.env = env


def ref_eval(prog: tuple, max_steps: int = 20_000) -> str:
    steps = 0

    def ev(env: dict[str, object], e: tuple) -> object:
        nonlocal steps
        steps += 1
        if steps > max_steps:
            raise StepLimitExceeded()
        tag = e[0]
        if tag in ("paren", "anno"):
            return ev(env, e[1])
        if tag in ("int", "bool"):
            return e[1]
        if tag == "var":
            return env[e[1]]
        if tag == "lam":
            return RefClosure(e[1], e[2], dict(env))
        if tag == "app":
            c = ev(env, e[1])
            assert isinstance(c, RefClosure)
            v = ev(env, e[2])
            ne = dict(c.env)
            ne[c.param] = v
            return ev(ne, c.body)
        if tag == "binop":
            op = e[1]
            a = ev(env, e[2])
            b = ev(env, e[3])
            assert type(a) is int and type(b) is int
            if op == "+":
                return a + b
            if op == "-":
                return a - b
            if op == "*":
                return a * b
            if op == "//":
                if b == 0:
                    raise RefRuntimeError()
                return a // b
            if op == "%":
                if b == 0:
                    raise RefRuntimeError()
                return a % b
            if op == "==":
                return a == b
            if op == "<":
                return a < b
            raise AssertionError(op)
        if tag == "if":
            return ev(env, e[2] if ev(env, e[1]) else e[3])
        if tag == "let":
            _, x, _, e1, e2 = e
            v1 = ev(env, e1)
            ne = dict(env)
            ne[x] = v1
            return ev(ne, e2)
        if tag == "letrec":
            _, f, _, lam_e, body = e
            re_env = dict(env)
            clos = RefClosure(lam_e[1], lam_e[2], re_env)
            re_env[f] = clos
            return ev(re_env, body)
        raise AssertionError(e)

    v = ev({}, prog)
    if type(v) is bool:
        return "True" if v else "False"
    if type(v) is int:
        return str(v)
    if isinstance(v, RefClosure):
        return "<function>"
    raise AssertionError(v)


def run_reference(raw: bytes) -> str:
    try:
        toks = ref_lex(raw)
        prog = RefParser(toks).parse()
    except RefParseError:
        return "ParseError"
    try:
        ref_synth([], prog)
    except RefTypeError:
        return "TypeError"
    try:
        return ref_eval(prog)
    except RefRuntimeError:
        return "RuntimeError"


def run_dut(raw: bytes) -> str:
    try:
        return mc.execute_bytes(raw)
    except mc.MCParseError:
        return "ParseError"
    except mc.MCTypeError:
        return "TypeError"
    except mc.MCRuntimeError:
        return "RuntimeError"


# ---------------------------------------------------------------------------
# Generators: Typed, Untyped, and Raw Token/Lexical Soup
# ---------------------------------------------------------------------------

NAMES = ["x", "y", "z", "f", "g", "_a", "k"]


def strip_outer_parens(ty: str) -> str:
    ty = ty.strip()
    while ty.startswith("(") and ty.endswith(")"):
        d = 0
        matched = True
        for i, ch in enumerate(ty):
            if ch == "(":
                d += 1
            elif ch == ")":
                d -= 1
                if d == 0 and i < len(ty) - 1:
                    matched = False
                    break
        if matched:
            ty = ty[1:-1].strip()
        else:
            break
    return ty


def split_arrow(ty: str) -> tuple[str, str]:
    ty = strip_outer_parens(ty)
    d = 0
    for i in range(len(ty) - 1):
        ch = ty[i]
        if ch == "(":
            d += 1
        elif ch == ")":
            d -= 1
        elif d == 0 and ty[i : i + 2] == "->":
            return ty[:i].strip(), ty[i + 2 :].strip()
    raise AssertionError(f"not an arrow type: {ty!r}")


def gen_type(rng: random.Random, depth: int = 0) -> str:
    if depth >= 2 or rng.random() < 0.6:
        return rng.choice(["Int", "Bool"])
    a = gen_type(rng, depth + 1)
    b = gen_type(rng, depth + 1)
    if "->" in a:
        a = f"({a})"
    return f"{a} -> {b}"


def gen_typed_expr(
    rng: random.Random, env: list[tuple[str, str]], target_ty: str, depth: int
) -> str:
    target_ty = strip_outer_parens(target_ty)
    latest: dict[str, str] = {}
    for n, t in env:
        latest[n] = strip_outer_parens(t)
    matching_vars = [n for n, t in latest.items() if t == target_ty]

    if depth <= 0:
        if matching_vars and rng.random() < 0.6:
            return rng.choice(matching_vars)
        if target_ty == "Int":
            v = rng.choice([0, 1, 2, 3, 5, 7, 10, -1, -7, -15])
            return str(v) if v >= 0 else f"(0 - {-v})"
        if target_ty == "Bool":
            return rng.choice(["True", "False"])
        dom, cod = split_arrow(target_ty)
        p = rng.choice(NAMES)
        body = gen_typed_expr(rng, env + [(p, dom)], cod, 0)
        return f"(/{p} -> {body})"

    choice = rng.random()
    if matching_vars and choice < 0.18:
        return rng.choice(matching_vars)

    if choice < 0.34:
        c = gen_typed_expr(rng, env, "Bool", depth - 1)
        t_b = gen_typed_expr(rng, env, target_ty, depth - 1)
        e_b = gen_typed_expr(rng, env, target_ty, depth - 1)
        return f"(if {c} then {t_b} else {e_b})"

    if choice < 0.52:
        nm = rng.choice(NAMES)
        bt = gen_type(rng, 1)
        be = gen_typed_expr(rng, env, bt, depth - 1)
        body = gen_typed_expr(rng, env + [(nm, bt)], target_ty, depth - 1)
        if rng.random() < 0.4:
            return f"(let {nm} : {bt} = {be} in {body})"
        return f"(let {nm} = {be} in {body})"

    if choice < 0.66:
        arg_ty = gen_type(rng, 1)
        fn_ty = f"({arg_ty}) -> ({target_ty})"
        fn_e = gen_typed_expr(rng, env, fn_ty, depth - 1)
        arg_e = gen_typed_expr(rng, env, arg_ty, depth - 1)
        if rng.random() < 0.25:
            return f"(({fn_e} : {fn_ty}) {arg_e})"
        return f"({fn_e} {arg_e})"

    if choice < 0.78:
        fn_name = rng.choice(["f", "g", "x"])
        p_name = rng.choice(["n", "x", "f"])
        limit_n = rng.randint(0, 5)
        base = gen_typed_expr(rng, env + [(p_name, "Int")], target_ty, depth - 1)
        if target_ty == "Int" and p_name != fn_name:
            step = f"({fn_name} ({p_name} - 1) + {base})"
        elif p_name != fn_name:
            step = f"({fn_name} ({p_name} - 1))"
        else:
            step = base
        cmp_rhs = rng.choice(["1", "0", "2"])
        cmp_op = rng.choice(["<", "=="])
        if cmp_op == "==":
            cmp_rhs = str(limit_n)
        lam = f"/{p_name} -> if {p_name} {cmp_op} {cmp_rhs} then {base} else {step}"
        if rng.random() < 0.35:
            lam = f"(({lam}))"
        body = gen_typed_expr(
            rng, env + [(fn_name, f"Int -> ({target_ty})")], target_ty, depth - 1
        )
        call_or_body = f"({fn_name} {limit_n})" if rng.random() < 0.6 else body
        return f"(let rec {fn_name} : Int -> ({target_ty}) = {lam} in {call_or_body})"

    if target_ty == "Int":
        op = rng.choice(["+", "-", "*", "//", "%"])
        a = gen_typed_expr(rng, env, "Int", depth - 1)
        b = gen_typed_expr(rng, env, "Int", depth - 1)
        return f"({a} {op} {b})"

    if target_ty == "Bool":
        op = rng.choice(["==", "<"])
        a = gen_typed_expr(rng, env, "Int", depth - 1)
        b = gen_typed_expr(rng, env, "Int", depth - 1)
        return f"({a} {op} {b})"

    dom, cod = split_arrow(target_ty)
    p = rng.choice(NAMES)
    body = gen_typed_expr(rng, env + [(p, dom)], cod, depth - 1)
    return f"(/{p} -> {body})"


def gen_untyped_expr(rng: random.Random, depth: int) -> str:
    if depth <= 0:
        return rng.choice(["0", "007", "1", "2", "True", "False", "x", "y", "f", "_a"])
    k = rng.randrange(8)
    if k == 0:
        p = rng.choice(NAMES)
        return f"/{p} -> {gen_untyped_expr(rng, depth - 1)}"
    if k == 1:
        a = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        if rng.random() < 0.3:
            return f"{a} {b}"
        return f"({a}) ({b})"
    if k == 2:
        op = rng.choice(["+", "-", "*", "//", "%", "==", "<"])
        a = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        if rng.random() < 0.3:
            return f"{a} {op} {b}"
        return f"({a}) {op} ({b})"
    if k == 3:
        c = gen_untyped_expr(rng, depth - 1)
        t = gen_untyped_expr(rng, depth - 1)
        e = gen_untyped_expr(rng, depth - 1)
        return f"if {c} then {t} else {e}"
    if k == 4:
        nm = rng.choice(NAMES)
        v = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        if rng.random() < 0.3:
            return f"let {nm} : {gen_type(rng, 1)} = {v} in {b}"
        return f"let {nm} = {v} in {b}"
    if k == 5:
        nm = rng.choice(NAMES)
        p = rng.choice(NAMES)
        ty = gen_type(rng, 1)
        fb = gen_untyped_expr(rng, depth - 1)
        b = gen_untyped_expr(rng, depth - 1)
        rhs = rng.choice([
            f"/{p} -> {fb}",
            f"(/{p} -> {fb})",
            f"(/{p} -> {fb} : {ty})",
            fb,
        ])
        return f"let rec {nm} : {ty} = {rhs} in {b}"
    if k == 6:
        e = gen_untyped_expr(rng, depth - 1)
        return f"({e} : {gen_type(rng, 1)})"
    e = gen_untyped_expr(rng, depth - 1)
    return rng.choice([
        f"{e} < 1 < 2",
        f"let rec f = /x -> {e} in f",
        f"({e}) /x -> x",
        f"let _ = {e} in 1",
        f"{e}--comment\n",
        f"1 + if True then {e} else 0",
    ])


SOUP_PIECES = [
    b"0", b"00", b"12", b"abc", b"_", b"_x", b"__", b"True", b"False", b"True1",
    b"Int", b"Bool", b"Foo", b"let", b"rec", b"in", b"if", b"then", b"else",
    b"match", b"with", b"type", b"forall",
    b"(", b")", b"->", b"/", b"//", b"///", b"+", b"-", b"--", b"---", b"-->",
    b"*", b"%", b"=", b"==", b"===", b"<", b"<=", b":",
    b" ", b"\t", b"\n", b"\r\n", b"\r", b"\f", b"\v",
    b"\x1c", b"\x00", b"\xc3\xa9", b"\xff", b">", b"!", b",",
]


def gen_token_soup(rng: random.Random) -> bytes:
    length = rng.randint(0, 18)
    return b"".join(rng.choice(SOUP_PIECES) for _ in range(length))


def main() -> None:
    rng = random.Random(20250302)
    t0 = time.perf_counter()
    outcomes: dict[str, int] = {}
    skipped = 0
    total = 24_000

    for i in range(total):
        mode = i % 3
        if mode == 0:
            tgt = gen_type(rng, 0)
            raw = gen_typed_expr(rng, [], tgt, rng.randint(1, 4)).encode("utf-8")
        elif mode == 1:
            raw = gen_untyped_expr(rng, rng.randint(1, 4)).encode("utf-8")
        else:
            raw = gen_token_soup(rng)

        try:
            ref_out = run_reference(raw)
        except StepLimitExceeded:
            skipped += 1
            continue
        dut_out = run_dut(raw)
        if ref_out != dut_out:
            print(f"MISMATCH on case #{i} (mode={mode})!")
            print(f"Raw: {raw!r}")
            print(f"Ref: {ref_out!r}")
            print(f"DUT: {dut_out!r}")
            sys.exit(1)
        key = (
            ref_out
            if ref_out
            in ("ParseError", "TypeError", "RuntimeError", "<function>", "True", "False")
            else "<int>"
        )
        outcomes[key] = outcomes.get(key, 0) + 1

    t1 = time.perf_counter()
    print(
        f"Full-pipeline differential fuzzing passed {total - skipped}/{total} cases "
        f"(skipped {skipped} non-terminating) in {t1 - t0:.2f}s"
    )
    print("Outcome distribution:", outcomes)


if __name__ == "__main__":
    main()
